callback_with_context.context_function_id:
#note: the 2nd argument to ClosePanel is required in order for CampaignHUDCallback::SetHUDVisibility(true) to be called#
( ritual_context = StoredContext("CcoCampaignRitual") ) =>
{
 DoIf( Components.IsNotInInactiveState,
  Do( ritual_context.RitualInteractionContext.ClearTarget, ritual_context.RitualInteractionContext.EnableTargetting(true), CreateComponent("UI/Campaign UI/dlc29_chs_planting_garden_of_nurgle_ritual_panel", RootComponent, this), ClosePanel("dlc29_chs_blessings_of_nurgle_panel_main", true) ) )
}

#note: the 2nd argument to ClosePanel is required in order for CampaignHUDCallback::SetHUDVisibility(true) to be called#
( ritual_context = StoredContext("CcoCampaignRitual") ) =>
{
 DoIf( Components.IsNotInInactiveState,
  Do( CampaignRoot.ClearSavedSelection, ritual_context.RitualInteractionContext.ClearTarget, ritual_context.RitualInteractionContext.EnableTargetting(true), CreateComponent("UI/Campaign UI/dlc29_chs_planting_garden_of_nurgle_ritual_panel", RootComponent, this) ) )
}

( gardens_list = PlayersFaction.SettlementList.Filter(StringStartsWith(SettlementType, "wh3_dlc29_woc_glottkin_garden_of_nurgle_"))
  , num_available_gardens = PlayersFaction.SettlementOwningLimitForGroup("wh3_dlc29_woc_glottkin_garden_of_nurgle_owning_limit") - gardens_list.Size
  , max_gardens = SharedStateReadFloat("glottkin_max_gardens_of_nurgle")
) =>
{
 Join(gardens_list, Generate(num_available_gardens, CcoRTGarden(Available: true)), Generate(max_gardens - num_available_gardens - gardens_list.Size, CcoRTGarden(Available: false)))
}
